CREATE TABLE IF NOT EXISTS materials(id UUID PRIMARY KEY,name VARCHAR(120) NOT NULL,category VARCHAR(80),total_stock INT NOT NULL,reserved_stock INT NOT NULL); CREATE TABLE IF NOT EXISTS material_assignments(id UUID PRIMARY KEY,material_id UUID NOT NULL,callout_id UUID NOT NULL,quantity INT NOT NULL); CREATE TABLE IF NOT EXISTS loans(id UUID PRIMARY KEY,material_id UUID NOT NULL,volunteer_id UUID NOT NULL,quantity INT NOT NULL,status VARCHAR(30) NOT NULL,loaned_at TIMESTAMP NOT NULL,closed_at TIMESTAMP);
